package mz.bam.seeky.android;
import android.content.*;import android.database.*;import android.text.*;import android.widget.*;import java.util.*;

public final class LibrarySearchActivity extends WorkspaceActivity {
    EditText query;LinearLayout results;int page,generation;String term="";
    static void open(Context c){c.startActivity(new Intent(c,LibrarySearchActivity.class));}String title(){return "Pesquisar no conteúdo";}
    void load(){if(query==null){query=PlusUi.input(this,"Palavras no texto dos livros","",200);content.addView(query);action("Pesquisar",()->{term=query.getText().toString().trim();page=0;search();});action("Preparar / actualizar pesquisa",()->{LibraryIndex.start(this);TaskService.open(this);});results=PlusUi.column(this);content.addView(results);}search();}
    void search(){if(results==null)return;int token=++generation,offset=page*30;String q=term;PlusUi.run(this,()->{List<StudyStore.Row> hits=new ArrayList<>();long indexed=0,partial=0,total=0;try(LibrarySearchStore db=new LibrarySearchStore(this)){db.scope();try(Cursor count=db.getReadableDatabase().rawQuery("SELECT COUNT(*),COALESCE(SUM(partial),0) FROM documents WHERE done=1",null)){count.moveToFirst();indexed=count.getLong(0);partial=count.getLong(1);}String match=LibrarySearchStore.match(q);if(!match.isEmpty()){try(Cursor count=db.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM texts WHERE texts MATCH ?",new String[]{match})){count.moveToFirst();total=count.getLong(0);}try(Cursor c=db.getReadableDatabase().rawQuery("SELECT s.material,s.part,s.start,s.body,s.digest,snippet(texts,'','',' … ',0,24) AS excerpt FROM texts JOIN segments s ON s.id=texts.docid WHERE texts MATCH ? LIMIT 30 OFFSET ?",new String[]{match,""+offset})){while(c.moveToNext())hits.add(TaskStore.row(c));}}}try(StudyStore books=new StudyStore(this)){for(StudyStore.Row hit:hits){StudyStore.Row book=books.get("materials",hit.n("material"));hit.put("title",book==null?AppLanguage.text(this,"Livro indisponível"):book.s("title"));}}final long ready=indexed,limited=partial,found=total;PlusUi.post(this,()->{if(token!=generation)return;results.removeAllViews();results.addView(label(ready+" "+AppLanguage.text(this,"livros preparados")+(limited>0?" · "+limited+" "+AppLanguage.text(this,"com conteúdo parcial"):""),12));if(getSharedPreferences("reading_tools",0).getBoolean("index_dirty",false))results.addView(label("Há alterações por indexar. Actualize a pesquisa.",12));if(q.isEmpty()){results.addView(label("Prepare a pesquisa uma vez. O texto e o OCR ficam no aparelho.",13));return;}results.addView(label(found+" "+AppLanguage.text(this,"ocorrências"),12));for(StudyStore.Row hit:hits){TextView item=label(hit.s("title")+" · "+AppLanguage.text(this,"Parte")+" "+(hit.n("part")+1)+"\n"+hit.s("excerpt"),14);UiBox.style(item);item.setGravity(android.view.Gravity.START);item.setOnClickListener(v->open(hit,q));results.addView(item);}LinearLayout nav=new LinearLayout(this);if(page>0){TextView b=label("Anterior",14);UiBox.style(b);b.setOnClickListener(v->{page--;search();});nav.addView(b,new LinearLayout.LayoutParams(0,-2,1));}if(offset+hits.size()<found){TextView b=label("Seguinte",14);UiBox.style(b);b.setOnClickListener(v->{page++;search();});nav.addView(b,new LinearLayout.LayoutParams(0,-2,1));}results.addView(nav);});});}
    void open(StudyStore.Row hit,String q){PlusUi.run(this,()->{StudyStore.Row book;try(StudyStore db=new StudyStore(this)){book=db.get("materials",hit.n("material"));}if(book==null)throw new java.io.IOException("O livro deixou de estar disponível. Actualize a pesquisa.");int part=(int)hit.n("part"),position=(int)hit.n("start");String text;try(SpeechDocument source=new SpeechDocument(this,StudyFileProvider.uri(this,book.id()),book.s("name"),book.s("mime"),()->false)){text=source.part(part);}if(!ReaderStore.digest(text).equals(hit.s("digest")))throw new java.io.IOException("O texto mudou. Actualize a pesquisa antes de abrir esta ocorrência.");String word=q.replace("\"","").replace("*","").trim().split("\\s+")[0];List<TextSearch.Match> occurrences=TextSearch.find(text,word,10000,true,false);if(occurrences.isEmpty())throw new java.io.IOException("O texto mudou. Actualize a pesquisa.");int chosen=occurrences.get(0).start;for(TextSearch.Match match:occurrences)if(match.start>=position){chosen=match.start;break;}final int offset=chosen;PlusUi.post(this,()->startActivity(new Intent(this,ReaderActivity.class).setDataAndType(StudyFileProvider.uri(this,book.id()),book.s("mime")).putExtra("name",book.s("name")).putExtra("study_title",book.s("title")).putExtra("study_material",book.id()).putExtra("study_segment",part).putExtra("search_offset",offset).putExtra("search_length",word.length())));});}
}
